import "core-js/modules/esnext.iterator.constructor.js";
import "core-js/modules/esnext.iterator.filter.js";
import "core-js/modules/esnext.iterator.map.js";
import "core-js/modules/esnext.iterator.reduce.js";
import { ref, computed, onMounted } from "vue";
import { db } from "@/firebase";
import { collection, addDoc, getDocs, updateDoc, deleteDoc, doc, onSnapshot, serverTimestamp } from "firebase/firestore";
export default {
  setup() {
    const payments = ref([]);
    const loading = ref(true);
    const isModalOpen = ref(false);
    const isViewingDetails = ref(false);
    const isConfirmingDelete = ref(false);
    const editMode = ref(false);
    const searchQuery = ref("");
    const statusFilter = ref("all");
    const fileName = ref("");
    const selectedFile = ref(null);
    const activePayment = ref({});
    const paymentData = ref({
      supplier: "",
      amount: "",
      status: "Pending",
      paymentMethod: "",
      paymentDate: "",
      invoiceNumber: "",
      description: ""
    });

    // Computed values for stats
    const pendingPaymentsCount = computed(() => payments.value.filter(payment => payment.status === "Pending").length);
    const paidPaymentsCount = computed(() => payments.value.filter(payment => payment.status === "Paid").length);
    const totalPaymentAmount = computed(() => payments.value.reduce((sum, payment) => sum + Number(payment.amount || 0), 0));
    const filteredPayments = computed(() => {
      let result = [...payments.value];

      // Apply status filter
      if (statusFilter.value !== "all") {
        result = result.filter(payment => payment.status === statusFilter.value);
      }

      // Apply search query
      if (searchQuery.value) {
        const query = searchQuery.value.toLowerCase();
        result = result.filter(payment => payment.supplier.toLowerCase().includes(query) || payment.invoiceNumber && payment.invoiceNumber.toLowerCase().includes(query) || payment.description && payment.description.toLowerCase().includes(query));
      }
      return result;
    });
    const fetchPayments = async () => {
      try {
        loading.value = true;

        // Set up real-time listener for payments collection
        const unsubscribe = onSnapshot(collection(db, "payments"), snapshot => {
          payments.value = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          }));
          loading.value = false;
        });

        // Return unsubscribe function for cleanup
        return unsubscribe;
      } catch (error) {
        console.error("Error fetching payments:", error);
        showNotification("Failed to fetch payments. Please try again.", "error");
        loading.value = false;
      }
    };
    const showAddModal = () => {
      editMode.value = false;
      resetForm();
      isModalOpen.value = true;
    };
    const closeModal = () => {
      isModalOpen.value = false;
    };
    const viewPayment = payment => {
      activePayment.value = {
        ...payment
      };
      isViewingDetails.value = true;
    };
    const closeViewModal = () => {
      isViewingDetails.value = false;
    };
    const resetForm = () => {
      paymentData.value = {
        supplier: "",
        amount: "",
        status: "Pending",
        paymentMethod: "",
        paymentDate: "",
        invoiceNumber: "",
        description: ""
      };
      fileName.value = "";
      selectedFile.value = null;
    };
    const editPayment = payment => {
      editMode.value = true;
      paymentData.value = {
        ...payment
      };

      // Close view modal if open
      if (isViewingDetails.value) {
        isViewingDetails.value = false;
      }
      isModalOpen.value = true;
    };
    const submitPayment = async () => {
      try {
        if (editMode.value) {
          // Update existing payment
          const paymentRef = doc(db, "payments", paymentData.value.id);
          await updateDoc(paymentRef, {
            ...paymentData.value,
            updatedAt: serverTimestamp()
          });
          showNotification("Payment updated successfully!");
        } else {
          // Add new payment
          await addDoc(collection(db, "payments"), {
            ...paymentData.value,
            createdAt: serverTimestamp()
          });
          showNotification("Payment added successfully!");
        }
        closeModal();
      } catch (error) {
        console.error("Error saving payment:", error);
        showNotification("Failed to save payment. Please try again.", "error");
      }
    };
    const confirmDelete = payment => {
      activePayment.value = payment;
      isConfirmingDelete.value = true;

      // Close view modal if open
      if (isViewingDetails.value) {
        isViewingDetails.value = false;
      }
    };
    const cancelDelete = () => {
      isConfirmingDelete.value = false;
    };
    const deletePayment = async () => {
      try {
        const paymentRef = doc(db, "payments", activePayment.value.id);
        await deleteDoc(paymentRef);
        showNotification("Payment deleted successfully!");
        isConfirmingDelete.value = false;
      } catch (error) {
        console.error("Error deleting payment:", error);
        showNotification("Failed to delete payment. Please try again.", "error");
      }
    };
    const handleFileUpload = event => {
      const file = event.target.files[0];
      if (file) {
        selectedFile.value = file;
        fileName.value = file.name;
      }
    };
    const formatDate = timestamp => {
      if (!timestamp) return "N/A";

      // If timestamp is a Firestore Timestamp, convert to JS Date
      const date = timestamp.toDate ? timestamp.toDate() : new Date(timestamp);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric"
      });
    };
    const formatCurrency = amount => {
      if (!amount) return "$0.00";
      return new Intl.NumberFormat("en-US", {
        style: "currency",
        currency: "USD"
      }).format(amount);
    };
    const showNotification = (message, type = "success") => {
      // Create notification element
      const notification = document.createElement("div");
      notification.className = `notification ${type}`;
      notification.textContent = message;
      document.body.appendChild(notification);

      // Add animation class after a short delay
      setTimeout(() => {
        notification.classList.add("show");
      }, 10);

      // Remove notification after timeout
      setTimeout(() => {
        notification.classList.remove("show");
        setTimeout(() => {
          document.body.removeChild(notification);
        }, 300);
      }, 3000);
    };
    onMounted(fetchPayments);
    return {
      payments,
      loading,
      isModalOpen,
      isViewingDetails,
      isConfirmingDelete,
      editMode,
      searchQuery,
      statusFilter,
      paymentData,
      activePayment,
      fileName,
      pendingPaymentsCount,
      paidPaymentsCount,
      totalPaymentAmount,
      filteredPayments,
      showAddModal,
      closeModal,
      viewPayment,
      closeViewModal,
      editPayment,
      submitPayment,
      confirmDelete,
      cancelDelete,
      deletePayment,
      handleFileUpload,
      formatDate,
      formatCurrency
    };
  }
};
